#include <stdio.h>
#include <string.h>

int roman_to_int(char *s) {
    int num = 0;
    int i = 0;
    while (s[i]) {
        if (s[i] == 'I' && s[i + 1] == 'V') {
            num += 4;
            i += 2;
        } else if (s[i] == 'I' && s[i + 1] == 'X') {
            num += 9;
            i += 2;
        } else if (s[i] == 'X' && s[i + 1] == 'L') {
            num += 40;
            i += 2;
        } else if (s[i] == 'X' && s[i + 1] == 'C') {
            num += 90;
            i += 2;
        } else if (s[i] == 'C' && s[i + 1] == 'D') {
            num += 400;
            i += 2;
        } else if (s[i] == 'C' && s[i + 1] == 'M') {
            num += 900;
            i += 2;
        } else if (s[i] == 'I') {
            num += 1;
            i++;
        } else if (s[i] == 'V') {
            num += 5;
            i++;
        } else if (s[i] == 'X') {
            num += 10;
            i++;
        } else if (s[i] == 'L') {
            num += 50;
            i++;
        } else if (s[i] == 'C') {
            num += 100;
            i++;
        } else if (s[i] == 'D') {
            num += 500;
            i++;
        } else if (s[i] == 'M') {
            num += 1000;
            i++;
        } else {
            return -1; // invalid Roman numeral
        }
    }
    return num;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <Roman numeral>\n", argv[0]);
        return 1;
    }
    int num = roman_to_int(argv[1]);
    if (num == -1) {
        printf("INVALID\n");
    } else {
        printf("%d\n", num);
    }
    return 0;
}
